m(label string, action func()) *MenuItem {\n31|\treturn &MenuItem{Label: label, Action: action}\n32|}\n33|\n34|// NewMenuItemSeparator creates a menu item that is to be used as a separator.\n35|func NewMenuItemSeparator() *MenuItem {\n36|\treturn &MenuItem{IsSeparator: true, Action: func() {}}\n37|}\n38|\n39|// MainMenu defines the data required to show a menu bar (desktop) or other appropriate top level menu.\n40|type MainMenu struct {\n41|\tItems []*Menu\n42|}\n43|\n44|// NewMainMenu creates a top level menu structure used by fyne.Window for displaying a menubar\n45|// (or appropriate equivalent).\n46|func NewMainMenu(items ...*Menu) *MainMenu {\n47|\treturn &MainMenu{items}\n48|}"}, {"tool_use_id": "toolu_fubmwYBIKErIMYwbznpESr", "content": "由于设置了show_linenos，以下返回信息为：(行号|)内容 。\n[FILE] 174 lines\n1|package fyne\n2|\n3|// Declare conformity to CanvasObject\n4|var _ CanvasObject = (*Container)(nil)\n5|\n6|// Container is a CanvasObject that contains a collection of child objects.\n7|// The layout of the children is set by the specified Layout.\n8|type Container struct {\n9|\tsize     Size     // The current size of the Container\n10|\tposition Position // The current position of the Container\n11|\tHidden   bool     // Is this Container hidden\n12|\n13|\tLayout  Layout         // The Layout algorithm for arranging child CanvasObjects\n14|\tObjects []CanvasObject // The set of CanvasObjects this container holds\n15|}\n16|\n17|// NewContainer returns a new Container instance holding the specified CanvasObjects.\n18|//\n19|// Deprecated: Use container.NewWithoutLayout() to create a container that uses manual layout.\n20|func NewContainer(objects ...CanvasObject) *Container {\n21|\treturn NewContainerWithoutLayout(objects...)\n22|}\n23|\n24|// NewContainerWithoutLayout returns a new Container instance holding the specified\n25|// CanvasObjects that are manually arranged.\n26|//\n27|// Deprecated: Use container.NewWithoutLayout() instead\n28|func NewContainerWithoutLayout(objects ...CanvasObject) *Container {\n29|\tret := &Container{\n30|\t\tObjects: objects,\n31|\t}\n32|\n33|\tret.size = ret.MinSize()\n34|\treturn ret\n35|}\n36|\n37|// NewContainerWithLayout returns a new Container instance holding the specified\n38|// CanvasObjects which will be laid out according to the specified Layout.\n39|//\n40|// Deprecated: Use container.New() instead\n41|func NewContainerWithLayout(layout Layout, objects ...CanvasObject) *Container {\n42|\tret := &Container{\n43|\t\tObjects: objects,\n44|\t\tLayout:  layout,\n45|\t}\n46|\n47|\tret.size = layout.MinSize(objects)\n48|\tret.layout()\n49|\treturn ret\n50|}\n51|\n52|// Add appends the specified object to the items this container manages.\n53|//\n54|// Since: 1.4\n55|func (c *Container) Add(add CanvasObject) {\n56|\tc.Objects = append(c.Objects, add)\n57|\tc.layout()\n58|}\n59|\n60|// AddObject adds another CanvasObject to the set this Container holds.\n61|//\n62|// Deprecated: Use replacement Add() function\n63|func (c *Container) AddObject(o CanvasObject) {\n64|\tc.Add(o)\n65|}\n66|\n67|// MinSize calculates the minimum size of a Container.\n68|// This is delegated to the Layout, if specified, otherwise it will mimic MaxLayout.\n69|func (c *Container) MinSize() Size {\n70|\tif c.Layout != nil {\n71|\t\treturn c.Layout.MinSize(c.Objects)\n72|\t}\n73|\n74|\tminSize := NewSize(1, 1)\n75|\tfor _, child := range c.Objects {\n76|\t\tminSize = minSize.Max(child.MinSize())\n77|\t}\n78|\n79|\treturn minSize\n80|}\n81|\n82|// Move the container (and all its children) to a new position, relative to its parent.\n83|func (c *Container) Move(pos Position) {\n84|\tc.position = pos\n85|}\n86|\n87|// Position gets the current position of this Container, relative to its parent.\n88|func (c *Container) Position() Position {\n89|\treturn c.position\n90|}\n91|\n92|// Resize sets a new size for the Container.\n93|func (c *Container) Resize(size Size) {\n94|\tif c.size == size {\n95|\t\treturn\n96|\t}\n97|\n98|\tc.