{"path": "task/workspace/data/validation/string.go", "start": 1, "lines": 41, "offset": 0, "total_lines": 41, "content": "package validation

import (
	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/data/binding"
)

// NewAllStrings creates a validator that applies a StringValidator to each string in a list.
// The validator will return the first error encountered, or nil if all items are valid.
//
// Since: 2.5
func NewAllStrings(itemValidator fyne.StringValidator) binding.ListValidator {
	return func(data binding.DataList) error {
		if itemValidator == nil {
			return nil
		}

		list, ok := data.(binding.StringList)
		if !ok {
			return nil // Not a string list, nothing to validate
		}

		length, err := list.Length()
		if err != nil {
			return err
		}

		for i := 0; i < length; i++ {
			item, err := list.GetValue(i)
			if err != nil {
				return err
			}

			if err := itemValidator(item); err != nil {
				return err
			}
		}

		return nil
	}
}
